INSERT INTO `faqs` (`id`, `category_id`, `question`, `answer`, `sort_order`, `status`, `created_at`, `updated_at`) VALUES
(1, 1, 'What is DayalStock?', 'DayalStock is a digital asset marketplace where you can find high-quality vectors, photos, and PSD files for your creative projects.', 0, 'published', '2026-07-19 07:31:30', '2026-07-19 07:31:30'),
(2, 1, 'Do I need an account to download free files?', '[PENDING CONFIRMATION: Yes, you must create a free account to download any files. / No, guests can download up to X free files.]', 0, 'published', '2026-07-19 07:31:30', '2026-07-19 07:31:30'),
(3, 2, 'Can I use downloaded assets for commercial projects?', '[PENDING CONFIRMATION: Details on commercial use, e.g., \'Yes, with a Premium subscription. Free users must attribute.\']', 0, 'published', '2026-07-19 07:31:30', '2026-07-19 07:31:30'),
(4, 2, 'Do I need to credit the author?', '[PENDING CONFIRMATION: Details on attribution, e.g., \'Free users must include a link back to DayalStock. Premium users do not need to attribute.\']', 0, 'published', '2026-07-19 07:31:30', '2026-07-19 07:31:30'),
(5, 3, 'How does the subscription download limit work?', '[PENDING CONFIRMATION: E.g., \'You receive 100 downloads per month. Unused downloads do not roll over to the next month.\']', 0, 'published', '2026-07-19 07:31:30', '2026-07-19 07:31:30'),
(6, 3, 'How do I cancel my subscription?', '[PENDING CONFIRMATION: E.g., \'You can cancel anytime from your Account Dashboard. You will retain access until the end of your billing cycle.\']', 0, 'published', '2026-07-19 07:31:30', '2026-07-19 07:31:30'),
(7, 4, 'How can I become a contributor?', 'Click on \'Become a Contributor\' in the footer, create an account, and submit your portfolio. [PENDING CONFIRMATION: \'Our team reviews applications within 3-5 business days.\']', 0, 'published', '2026-07-19 07:31:30', '2026-07-19 07:31:30'),
(8, 4, 'How much money can I make?', '[PENDING CONFIRMATION: E.g., \'You earn 30% of the net subscription revenue for your downloads. Refer to our Contributor Guidelines for exact details.\']', 0, 'published', '2026-07-19 07:31:30', '2026-07-19 07:31:30');
